'use strict';
const KEY='hadas-balance-v1';
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shift=(date,n)=>{let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)};
const clone=x=>JSON.parse(JSON.stringify(x));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
const defaults=()=>({version:1,settings:{calories:null,protein:null,carbs:null,fat:null,fiber:null,water:null,cupMl:250,activityWeight:null,steps:null,workouts:null,weighDays:[],drinkTypes:['מים'],visible:{sleep:true,quality:true,energy:true,mood:true,stress:true,bloat:true,bowel:true,cycle:true,weight:true},reminders:[]},days:{},foods:[],templates:[],breakfast:null,weekly:{}});
function validate(x){if(!x||x.version!==1||!x.settings||!x.days||Array.isArray(x.days)||!Array.isArray(x.foods)||!Array.isArray(x.templates)||!x.weekly)throw Error('קובץ הגיבוי אינו תואם לאפליקציה');for(const [k,d] of Object.entries(x.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!d||!Array.isArray(d.meals)||!Array.isArray(d.drinks)||!Array.isArray(d.activities)||!d.goals||!d.morning||!d.evening||!Array.isArray(d.evening.thanks)||!d.tomorrow||!d.body)throw Error('קובץ הגיבוי כולל יום לא תקין');for(let m of d.meals)if(!Array.isArray(m.items)||!m.habits)throw Error('קובץ הגיבוי כולל ארוחה לא תקינה');}if(!Array.isArray(x.settings.drinkTypes)||!x.settings.visible||!Array.isArray(x.settings.reminders))throw Error('הגדרות הגיבוי אינן תקינות');return x;}
let db;let startupError='';try{const raw=localStorage.getItem(KEY);db=raw?validate(JSON.parse(raw)):defaults()}catch(e){db=defaults();startupError='לא הצלחתי לקרוא את הנתונים השמורים. הורידי גיבוי של הנתונים הקיימים לפני החלפתם.'}
db.settings.cupMl=db.settings.cupMl||250;
let selected=localDate(),tab='morning',safeToSave=!startupError;
const focuses=['אכילה ללא הסחות דעת','הנחת מזלג בין ביסים','תשומת לב לרעב ולשובע','ארוחות מתוכננות','שתייה','תנועה','שינה','דיבור מכבד לעצמי'];
const habits=[['fork','האם הנחתי את המזלג בין ביסים?'],['distractions','האם אכלתי ללא הסחות דעת?'],['snacking','האם נמנעתי מנשנוש לא מתוכנן מאז הארוחה הקודמת?']];
const drinks=['מים','קפה','תה','חלב','משקה אחר'];
const bodyLabels={sleep:'שעות שינה בלילה הקודם',quality:'איכות שינה',energy:'רמת אנרגיה',mood:'מצב רוח',stress:'רמת לחץ',bloat:'נפיחות',bowel:'האם הייתה לי יציאה?',cycle:'מחזור ותסמינים',weight:'משקל והיקפים'};
function newDay(date){const prev=db.days[shift(date,-1)]?.tomorrow;return{goals:clone(db.settings),touched:false,morning:{focus:[],custom:prev?.focus||'',step:'',challenge:'',response:'',meals:prev?plannedMeals(prev):'',activity:prev?.movement||'',inherited:prev?clone(prev):null},meals:[],drinks:[],activities:[],exercise:'',steps:null,body:{},full:false,evening:{thanks:Array(10).fill(''),help:'',continue:'',learn:'',self:'',calorieAnswer:''},tomorrow:{focus:'',help:'',prep:'',movement:'',challenge:'',tasks:[]}}}
function day(){return db.days[selected]||(db.days[selected]=newDay(selected))}
function save(touched=true){if(touched)day().touched=true;try{if(!safeToSave)throw Error('הורידי תחילה את הגיבוי הקיים');localStorage.setItem(KEY,JSON.stringify(db));document.getElementById('saveState').textContent='נשמר במכשיר'}catch(e){document.getElementById('saveState').textContent='השמירה לא הצליחה';toast(e.message)} }
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3200)}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x==null?'טרם דיווחת':Number(x).toLocaleString('he-IL',{maximumFractionDigits:1});
function get(path){let a=path.split('.'),o=a.shift()==='day'?day():db;for(let k of a)o=o?.[k];return o}
function set(path,value){let a=path.split('.'),o=a.shift()==='day'?day():db;for(let k of a.slice(0,-1)){if(!o[k])o[k]={};o=o[k]}o[a.at(-1)]=value}
function field(label,path,type='text',opts={}){const v=get(path);const id='f-'+path.replaceAll('.','-');let input;if(type==='textarea')input=`<textarea placeholder="${esc(opts.placeholder||'')}" id="${id}" data-path="${path}">${esc(v)}</textarea>`;else if(type==='select')input=`<select id="${id}" data-path="${path}"><option value="">טרם דיווחת</option>${opts.options.map(x=>`<option value="${esc(x)}" ${String(v)===String(x)?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else input=`<input id="${id}" data-path="${path}" type="${type}" value="${esc(v)}" ${type==='number'?`min="${opts.min??0}" step="${opts.step??'any'}" ${opts.max!=null?`max="${opts.max}"`:''}`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>`;return `<div class="field"><label for="${id}">${label}</label>${input}</div>`}
function check(label,path){return `<label class="check"><input type="checkbox" data-path="${path}" ${get(path)?'checked':''}>${label}</label>`}
function answers(label,path,options=['כן','חלקית','לא','לא רלוונטי']){return `<div class="answer"><label>${label}</label><div class="chips">${options.map(x=>`<button class="chip ${(path.endsWith('.planned')?(get(path)?'מתוכננת':'לא מתוכננת'):get(path))===x?'selected':''}" data-action="answer" data-path="${path}" data-value="${esc(x)}" aria-pressed="${(path.endsWith('.planned')?(get(path)?'מתוכננת':'לא מתוכננת'):get(path))===x}">${x}</button>`).join('')}<button class="small" data-action="answer" data-path="${path}" data-value="">ניקוי</button></div></div>`}
function totals(d){const items=d.meals.flatMap(m=>m.items);const complete=items.length>0&&items.every(i=>Number.isFinite(i.qty)&&i.qty>0&&Number.isFinite(i.base)&&i.base>0&&Number.isFinite(i.cal)&&Number.isFinite(i.pro));return{n:items.length,complete,estimated:items.some(i=>i.estimated),cal:items.reduce((a,i)=>a+(i.qty>0&&i.base>0&&i.cal!=null?i.qty/i.base*i.cal:0),0),pro:items.reduce((a,i)=>a+(i.qty>0&&i.base>0&&i.pro!=null?i.qty/i.base*i.pro:0),0)}}
function liquid(d,types=null){if(!d.drinks.length)return null;return d.drinks.filter(x=>!types||types.includes(x.type)).reduce((a,x)=>a+x.amount,0)}
function stat(label,value,goal,unit=''){return `<div class="stat"><label>${label}</label><strong>${value==null?'טרם דיווחת':fmt(value)+' '+unit}</strong><small>${goal!=null?'יעד '+fmt(goal)+' '+unit:'ללא יעד מוגדר'}</small>${goal>0&&value!=null?`<div class="bar"><i style="width:${Math.min(value/goal*100,100)}%"></i></div>`:''}</div>`}
function refreshSummary(){const d=day(),t=totals(d);document.getElementById('stats').innerHTML=`<span>קלוריות: ${metricTotal(d,'cal').value==null?'טרם דיווחת':fmt(metricTotal(d,'cal').value)}</span><span>חלבון: ${metricTotal(d,'pro').value==null?'טרם דיווחת':fmt(metricTotal(d,'pro').value)+' ג׳'}</span><details class="nutrient-overview"><summary>כל הערכים מול היעדים שלי</summary>${goalTable(d)}</details>`;document.getElementById('focusSummary').textContent=[d.morning.custom,...d.morning.focus].filter(Boolean).join(' · ')||'מה חשוב לי היום?';}
function morningView(){const d=day();return `<section class="card journal"><span class="eyebrow">עמוד חדש ביומן שלי</span><h2>על מה אני בוחרת לשים דגש היום?</h2>${field('המקום שלי לכתוב','day.morning.custom','textarea',{placeholder:'דבר אחד שחשוב לי היום…'})}<details><summary>רעיונות לדגש</summary><div class="chips">${focuses.map(f=>`<button class="chip ${d.morning.focus.includes(f)?'selected':''}" data-action="focus" data-value="${f}">${f}</button>`).join('')}</div></details></section><section class="card"><h2>התכנון שלי להיום</h2>${field('מה אני מתכננת לאכול?','day.morning.meals','textarea')}${field('איך אשלב תנועה?','day.morning.activity','textarea')}${d.morning.inherited?`<details><summary>מה הכנתי אתמול להיום</summary><p>${esc(d.morning.inherited.help)}</p><p>${esc(d.morning.inherited.prep)}</p><p>${esc(d.morning.inherited.challenge)}</p><p>${esc(d.morning.inherited.tasks.join(' · '))}</p></details>`:''}<details><summary>עוד רגע לעצמי, אם ארצה</summary>${field('איזה צעד קטן אעשה היום?','day.morning.step','textarea')}${field('מה עלול להקשות עליי?','day.morning.challenge','textarea')}${field('אם זה יקרה, מה אעשה?','day.morning.response','textarea')}</details></section><div class="quick-grid">${[['food','אוכל','מה אכלתי'],['water','שתייה','עוד כוס'],['movement','תנועה','פעילות וצעדים'],['evening','סוף יום','תודות ומחר']].map(([v,l,n])=>`<button data-action="tab" data-value="${v}"><strong>${l}</strong><small>${n}</small></button>`).join('')}</div>`}
function mealType(x){return({breakfast:'בוקר',lunch:'צהריים',dinner:'ערב',snack:'ביניים'})[x]||x}
function detailedItemView(item,mi,ii){let p=`day.meals.${mi}.items.${ii}`;return `<div class="item"><div class="item-grid">${field('שם המזון',p+'.name')}${field('כמות שאכלתי',p+'.qty','number',{step:'any'})}${field('יחידת מידה',p+'.unit','select',{options:['גרם','מ״ל','יחידה','כף','כפית','כוס','מנה']})}</div><p class="hint">הזיני ערכים מהתווית לכמות בסיס באותה יחידה. למשל: בסיס 100 גרם, 120 קלוריות ו־8 גרם חלבון.</p><div class="values">${field('כמות בסיס',p+'.base','number')}${field('קלוריות לכמות הבסיס',p+'.cal','number')}${field('חלבון לכמות הבסיס, גרם',p+'.pro','number')}</div><details><summary>פחמימות, שומן וסיבים מהתווית</summary><div class="values">${[['carbs','פחמימות'],['fat','שומן'],['fiber','סיבים']].map(([k,l])=>field(l+' לכמות הבסיס, גרם',p+'.'+k,'number')).join('')}</div><p class="hint">הזיני ערכים לאותה כמות בסיס. השאירי ריק אם אין נתון. אפס מתאים רק כשידוע שהערך הוא אפס.</p></details>${check('הערכים הם הערכה שלי',p+'.estimated')}<div class="row"><span class="muted" id="item-total-${mi}-${ii}">${itemTotal(item)}</span><button class="small" data-action="saveFood" data-mi="${mi}" data-ii="${ii}">שמירת מזון</button><button class="small danger" data-action="removeItem" data-mi="${mi}" data-ii="${ii}">מחיקת פריט</button></div></div>`}
function itemTotal(i){return nutrientText({meals:[{items:[i]}]})}
function mealView(m,mi){const p=`day.meals.${mi}`,t=totals({meals:[m]});return `<details class="card meal" ${!m.items.length?'open':''}><summary><span>${mealType(m.type)}${m.type==='snack'?' · '+(m.planned?'מתוכננת':'לא מתוכננת'):''}</span><small id="meal-summary-${mi}">${compactNutrition({meals:[m]})}</small></summary><div class="row">${field('שעת הארוחה',p+'.time','time')}<button class="small danger" data-action="removeMeal" data-mi="${mi}">מחיקת ארוחה</button></div>${m.type==='snack'?answers('הביניים שלי',p+'.planned',['מתוכננת','לא מתוכננת']):''}<div id="meal-total-${mi}" class="badge">${nutrientText({meals:[m]})}</div>${m.items.map((i,ii)=>itemView(i,mi,ii)).join('')}<div class="row"><button data-action="addItem" data-mi="${mi}">+ מזון</button>${db.foods.length?`<select id="saved-food-${mi}" aria-label="מזון שמור"><option value="">בחרי מזון שמור</option>${db.foods.map((f,i)=>`<option value="${i}">${esc(f.name)}</option>`).join('')}</select><button data-action="useFood" data-mi="${mi}">הוספה משמורים</button>`:''}</div><details><summary>הרגלי אכילה והערה, לבחירתי</summary>${habits.map(([k,l])=>answers(l,p+'.habits.'+k)).join('')}${field('רעב לפני, 0 עד 10',p+'.hunger','select',{options:Array.from({length:11},(_,i)=>String(i))})}${field('שובע אחרי: 0 ללא שובע, 10 מלאות לא נעימה',p+'.satiety','select',{options:Array.from({length:11},(_,i)=>String(i))})}${field('מה השפיע עליי?',p+'.influence','select',{options:['רעב','הנאה','לחץ','שעמום','עייפות','חברה','אחר']})}${field('הערה לעצמי',p+'.note','textarea')}</details><details><summary>שמירת הארוחה לשימוש חוזר</summary><button data-action="saveMeal" data-mi="${mi}">שמירת ארוחה קבועה</button>${m.type==='breakfast'?`<button data-action="saveBreakfast" data-mi="${mi}">הגדרה כבוקר הקבוע שלי</button>`:''}</details></details>`}
function foodView(){const d=day(),prev=db.days[shift(selected,-1)];return `<section class="card"><h2>האוכל שלי</h2>${d.morning.meals?`<details><summary>התכנון להיום</summary><p class="plan-text">${esc(d.morning.meals)}</p></details>`:''}<div class="chips">${['breakfast','lunch','dinner'].map(t=>`<button data-action="addMeal" data-value="${t}">+ ${mealType(t)}</button>`).join('')}</div><div class="chips section-space"><button data-action="plannedSnack">+ ביניים מתוכננת</button><button data-action="unplannedSnack">+ ביניים לא מתוכננת</button></div><details><summary>ארוחות קבועות ומאתמול</summary><button data-action="useBreakfast">הבוקר הקבוע שלי</button>${prev?.meals.length?`<select id="copy-meal" aria-label="ארוחה מאתמול">${prev.meals.map((m,i)=>`<option value="${i}">${mealType(m.type)} · ${esc(m.items.map(i=>i.name).join(', '))}</option>`).join('')}</select><button data-action="copyMeal">הוספה מאתמול</button>`:''}${db.templates.length?`<select id="template-meal" aria-label="ארוחה קבועה">${db.templates.map((m,i)=>`<option value="${i}">${esc(m.title)}</option>`).join('')}</select><button data-action="useTemplate">הוספה מארוחות קבועות</button>`:''}</details>${check('סיימתי לדווח את כל האוכל היום','day.full')}</section>${d.meals.length?d.meals.map(mealView).join(''):'<div class="empty">בחרי ארוחה כדי להתחיל.</div>'}`}
function legacyBodyView(){const d=day();return `<section class="card"><h2>שתייה</h2><p class="hint">מים: ${fmt(liquid(d,['מים']))} מ״ל · כל הנוזלים: ${fmt(liquid(d))} מ״ל</p><div class="chips"><button class="primary" data-action="water" data-value="250">+ 250 מ״ל מים</button><button data-action="water" data-value="500">+ 500 מ״ל מים</button></div><form id="drink-form" class="grid"><div class="field"><label for="drink-type">סוג משקה</label><select id="drink-type">${drinks.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="drink-amount">כמות במ״ל</label><input id="drink-amount" type="number" min="1" step="any" required></div><button type="submit">הוספת שתייה</button></form>${d.drinks.map((x,i)=>`<div class="log"><span>${esc(x.type)} · ${fmt(x.amount)} מ״ל</span><div class="log-actions"><button class="small" data-action="editDrink" data-index="${i}">עריכה</button><button class="small danger" data-action="removeDrink" data-index="${i}">מחיקה</button></div></div>`).join('')}</section><section class="card"><h2>תנועה וצעדים</h2>${d.morning.activity?`<div class="note">התכנון שלי: ${esc(d.morning.activity)}</div>`:''}${answers('האם התעמלתי היום?','day.exercise',['כן','לא'])}${field('מספר הצעדים שלי','day.steps','number',{step:1})}<p class="hint">הזיני ידנית מהטלפון או מהשעון שלך.</p><form id="activity-form"><div class="grid"><div class="field"><label for="activity-type">סוג פעילות</label><select id="activity-type"><option>הליכה</option><option>אימון כוח</option><option>יוגה</option><option>תנועתיות</option><option>אחר</option></select></div><div class="field"><label for="activity-minutes">משך בדקות</label><input id="activity-minutes" type="number" min="1" required></div></div><div class="field"><label for="activity-note">הערה או שם הפעילות</label><input id="activity-note"></div><button type="submit">הוספת פעילות</button></form>${d.activities.map((a,i)=>`<div class="log"><span>${esc(a.type)} · ${fmt(a.minutes)} דקות ${esc(a.note)}</span><div class="log-actions"><button class="small" data-action="editActivity" data-index="${i}">עריכה</button><button class="small danger" data-action="removeActivity" data-index="${i}">מחיקה</button></div></div>`).join('')}</section><section class="card"><h2>איך אני מרגישה?</h2><p class="hint">כל השדות כאן לבחירתך. תוכלי להסתיר אותם בהגדרות.</p><div class="grid">${Object.entries(bodyLabels).filter(([k])=>k!=='weight'&&db.settings.visible[k]).map(([k,l])=>field(l,'day.body.'+k,k==='sleep'?'number':k==='cycle'?'textarea':'select',{max:24,options:k==='quality'?['טובה','בינונית','לא טובה']:k==='bowel'?['כן','לא']:k==='bloat'?['אין','קלה','בינונית','חזקה']:k==='mood'?['טוב','בינוני','קשה']:['נמוכה','בינונית','גבוהה']})).join('')}</div>${db.settings.visible.weight?`<div class="grid">${field('משקל, ק״ג','day.body.weight','number',{step:.1,min:1})}${field('היקף מותניים, ס״מ','day.body.waist','number',{step:.1,min:1})}</div>`:''}</section>`}
const prepTasks=['הכנת ארוחה','מילוי בקבוק','קניית מצרכים','הכנת בגדי אימון'];
function eveningView(){const d=day();return `<section class="card"><span class="eyebrow">מבט קצר על היום</span><h2>מה יכול לעזור לי מחר?</h2><div id="evening-goals">${goalTable(d)}</div>${feedback(d).map(x=>`<p class="note">${esc(x)}</p>`).join('')}${field('מה אוכל לעשות טוב יותר מחר?','day.evening.improve','textarea')}<details><summary>מה עזר ומה הקשה היום?</summary><p class="hint">בחרי רק מה שמתאים. הבחירות ירוכזו בסיכום השבועי.</p>${reflectionChips('הצלחות ודברים שעזרו','successes',successOptions)}${reflectionChips('חסמים ודברים שהקשו','barriers',barrierOptions)}${field('הצלחה שחשוב לי לזכור','day.evening.successNote','textarea')}${field('חסם שארצה להבין','day.evening.barrierNote','textarea')}</details><details><summary>עוד מקום לסיכום אישי</summary>${field('מה עזר לי היום?','day.evening.help','textarea')}${field('מה ארצה להמשיך?','day.evening.continue','textarea')}${field('מה למדתי?','day.evening.learn','textarea')}${field('מה אגיד לעצמי עכשיו?','day.evening.self','textarea')}${answers('האם עמדתי ביעד הקלורי שקבעתי?','day.evening.calorieAnswer',['כן','חלקית','לא','לא יודעת'])}</details></section><section class="card journal"><h2>עשרה דברים שאני מודה עליהם היום</h2><p class="hint">גם דברים קטנים מתאימים. אפשר לכתוב כמה שמתאים לך.</p><div class="gratitude">${d.evening.thanks.map((v,i)=>`<label><span>${i+1}</span><textarea aria-label="תודה מספר ${i+1}" data-path="day.evening.thanks.${i}" placeholder="אני מודה על…">${esc(v)}</textarea></label>`).join('')}</div></section><section class="card"><h2>מכינה את מחר</h2>${field('הדגש שלי למחר','day.tomorrow.focus','textarea')}<div class="grid">${[['breakfast','בוקר'],['lunch','צהריים'],['dinner','ערב'],['snacks','ביניים']].map(([k,l])=>field('מה אני מתכננת לאכול ב'+l+'?','day.tomorrow.menu.'+k,'textarea')).join('')}</div>${field('איך אני מתכוונת להתנהל מחר?','day.tomorrow.help','textarea')}${field('מה כדאי להכין מראש?','day.tomorrow.prep','textarea')}${field('מתי אשלב תנועה?','day.tomorrow.movement','textarea')}<details><summary>להיערך למצב מאתגר</summary>${field('מה עלול להקשות ומה אעשה?','day.tomorrow.challenge','textarea')}<div class="chips">${prepTasks.map(x=>`<button class="chip ${d.tomorrow.tasks.includes(x)?'selected':''}" data-action="task" data-value="${x}">${x}</button>`).join('')}</div></details><p class="hint">התכנון יעבור לתחילת היום הבא. אם כבר מילאת שם, הוא יופיע כהיערכות מאתמול.</p></section>`}
function weekDates(){return Array.from({length:7},(_,i)=>shift(selected,i-6))}
const average=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
function weeklyStats(){let dates=weekDates(),ds=dates.map(x=>db.days[x]).filter(d=>d?.touched),complete=ds.filter(d=>d.full&&totals(d).complete);return {dates,ds,complete,water:ds.filter(d=>d.drinks.length).map(d=>liquid(d,d.goals.drinkTypes)),steps:ds.filter(d=>d.steps!=null).map(d=>d.steps),acts:ds.flatMap(d=>d.activities)}}
function graph(key){const data=Object.entries(db.days).filter(([k,d])=>d.body[key]!=null&&d.body[key]!==''&&k<=selected).sort((a,b)=>a[0].localeCompare(b[0])).slice(-30).map(([date,d])=>({date,v:Number(d.body[key])}));if(!data.length)return '<div class="empty">כשתזיני מדידות, הגרף יופיע כאן.</div>';let min=Math.min(...data.map(x=>x.v)),max=Math.max(...data.map(x=>x.v)),span=Math.max(max-min,1),pts=data.map((x,i)=>[50+(data.length===1?.5:i/(data.length-1))*590,135-(x.v-min)/span*90]);return `<svg class="chart" viewBox="0 0 700 190" role="img" aria-label="גרף ${key==='weight'?'משקל':'היקף מותניים'}"><text x="20" y="38">${fmt(max)}</text><text x="20" y="140">${fmt(min)}</text><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#27665b" stroke-width="3"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#27665b"><title>${data[i].date}: ${data[i].v}</title></circle>`).join('')}<text x="50" y="173">${data[0].date}</text><text x="535" y="173">${data.at(-1).date}</text></svg>`}
function legacyTrendsView(){const w=weeklyStats(),weights=w.ds.filter(d=>d.body.weight!=null).map(d=>Number(d.body.weight));if(!db.weekly[selected])db.weekly[selected]={continue:'',change:''};return `<section class="card"><h2>השבוע שלי</h2><p class="hint">שבעת הימים מ־${w.dates[0]} עד ${selected}. ימים ללא דיווח לא נחשבים לאי עמידה ביעד.</p><div class="grid"><div class="note">${w.ds.length} ימים עם דיווח מתוך 7<br>שתייה ממוצעת ביעד: ${fmt(average(w.water))} מ״ל (${w.water.length} ימים)<br>צעדים בממוצע: ${fmt(average(w.steps))} (${w.steps.length} ימים)</div><div class="note">${w.acts.length} פעילויות · ${fmt(w.acts.reduce((s,a)=>s+a.minutes,0))} דקות<br>יעד אימונים שבועי ליום הנבחר: ${fmt(day().goals.workouts)}<br>קלוריות ממוצעות: ${fmt(average(w.complete.map(d=>totals(d).cal)))}<br>חלבון ממוצע: ${fmt(average(w.complete.map(d=>totals(d).pro)))} ג׳<br>על בסיס ${w.complete.length} ימים עם דיווח מזון מלא וערכים לכל הפריטים</div></div><h3>הרגלי האכילה שלי</h3>${habits.map(([k,l])=>{let a=w.ds.flatMap(d=>d.meals.map(m=>m.habits[k])).filter(x=>x&&x!=='לא רלוונטי');return `<p>${l}<br><span class="muted">${a.length} תשובות רלוונטיות: ${['כן','חלקית','לא'].map(x=>x+' '+a.filter(v=>v===x).length).join(' · ')}</span></p>`}).join('')}<h3>הדגשים שבחרתי</h3><p class="muted">${esc([...new Set(w.ds.flatMap(d=>[...d.morning.focus,d.morning.custom].filter(Boolean)))].join(' · '))||'טרם בחרת דגשים'}</p>${field('מה ארצה להמשיך בשבוע הבא?','root.weekly.'+selected+'.continue','textarea')}${field('מה ארצה לשנות כדי שיהיה לי קל יותר?','root.weekly.'+selected+'.change','textarea')}</section>${db.settings.visible.weight?`<section class="card"><h2>המדידות שלי</h2><p class="hint">משקל ממוצע בשבעת הימים: ${fmt(average(weights))} ק״ג · ${weights.length} מדידות. הגרפים מציגים עד 30 מדידות עד לתאריך הנבחר.</p><h3>משקל</h3>${graph('weight')}<h3 class="section-space">היקף מותניים</h3>${graph('waist')}<div class="table-wrap"><table><thead><tr><th>תאריך</th><th>משקל</th><th>היקף</th></tr></thead><tbody>${Object.entries(db.days).filter(([k,d])=>d.body.weight!=null||d.body.waist!=null).sort((a,b)=>b[0].localeCompare(a[0])).map(([k,d])=>`<tr><td><button class="small" data-action="date" data-value="${k}">${k}</button></td><td>${fmt(d.body.weight)}</td><td>${fmt(d.body.waist)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="card"><h2>תחושה לאורך זמן</h2><div class="table-wrap"><table><thead><tr><th>יום</th>${Object.entries(bodyLabels).filter(([k])=>k!=='weight'&&db.settings.visible[k]).map(([k,v])=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${w.dates.map(k=>`<tr><td>${k.slice(5)}</td>${Object.entries(bodyLabels).filter(([key])=>key!=='weight'&&db.settings.visible[key]).map(([key])=>`<td>${esc(db.days[k]?.body[key]??'טרם דיווחת')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function legacySettingsView(){const s=db.settings;return `<section class="card"><h2>היעדים שלי</h2><p class="hint">בחרי בעצמך. אפשר להשאיר יעד ריק. השינויים יחולו על ימים חדשים. ימים שכבר פתחת שומרים את היעדים שלהם.</p><div class="grid">${[['calories','קלוריות ביום'],['protein','חלבון ביום, גרם'],['carbs','פחמימות ביום, גרם'],['fat','שומן ביום, גרם'],['fiber','סיבים ביום, גרם'],['water','שתייה ביום, מ״ל'],['steps','צעדים ביום'],['workouts','אימונים בשבוע']].map(([k,l])=>field(l,'root.settings.'+k,'number')).join('')}</div><button data-action="applyGoals">החלת היעדים החדשים על היום הנבחר</button><p class="hint">הפעולה משנה רק את היעדים של ${selected}.</p><h3>מה נכלל ביעד השתייה?</h3><div class="chips">${drinks.map(x=>`<button class="chip ${s.drinkTypes.includes(x)?'selected':''}" data-action="drinkType" data-value="${x}" aria-pressed="${s.drinkTypes.includes(x)}">${x}</button>`).join('')}</div><h3 class="section-space">ימים שבהם ארצה להישקל</h3><div class="chips">${['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'].map((x,i)=>`<button class="chip ${s.weighDays.includes(i)?'selected':''}" data-action="weighDay" data-value="${i}" aria-pressed="${s.weighDays.includes(i)}">${x}</button>`).join('')}</div></section><section class="card"><h2>מה ארצה לראות?</h2><div class="grid">${Object.entries(bodyLabels).map(([k,l])=>check(l,'root.settings.visible.'+k)).join('')}</div></section><section class="card"><h2>תזכורות בתוך האפליקציה</h2><p class="hint">התזכורות מופיעות כשהאפליקציה פתוחה ביום הנוכחי. הן לא נשלחות כשהיא סגורה.</p><form id="reminder-form"><div class="grid"><div class="field"><label for="reminder-time">שעה</label><input id="reminder-time" type="time" required></div><div class="field"><label for="reminder-text">מה להזכיר לי?</label><input id="reminder-text" required></div></div><button type="submit">הוספת תזכורת</button></form>${s.reminders.map((r,i)=>`<div class="log"><span>${esc(r.time)} · ${esc(r.text)}</span><button class="small danger" data-action="removeReminder" data-index="${i}">מחיקה</button></div>`).join('')}</section><section class="card"><h2>מזונות וארוחות שמורות</h2>${db.foods.map((f,i)=>`<div class="log"><span>${esc(f.name)}</span><button class="small danger" data-action="deleteFood" data-index="${i}">מחיקה</button></div>`).join('')}${db.templates.map((m,i)=>`<div class="log"><span>${esc(m.title)}</span><button class="small danger" data-action="deleteTemplate" data-index="${i}">מחיקה</button></div>`).join('')}<p class="hint">${db.breakfast?'הבוקר הקבוע מוגדר. תוכלי להחליף אותו מתוך ארוחת בוקר.':'הגדירי את הבוקר הקבוע מתוך ארוחת בוקר שתדווחי.'}</p>${db.breakfast?'<button data-action="clearBreakfast">מחיקת הבוקר הקבוע</button>':''}</section><section class="card"><h2>הנתונים נשארים אצלך</h2><p class="hint">נתוני הדיווח נשמרים בדפדפן במכשיר הזה, ולא נשלחים לשירות חיצוני. מחיקת נתוני הדפדפן או מעבר למכשיר אחר לא יעבירו את הנתונים. שמרי גיבוי כדי שתוכלי לשחזר אותם.</p><div class="chips"><button class="primary" data-action="backup">הורדת גיבוי מלא</button><button data-action="csv">ייצוא טבלת CSV</button></div><div class="field"><label for="import-file">שחזור מקובץ גיבוי JSON</label><input id="import-file" type="file" accept="application/json,.json"></div><button class="danger" data-action="reset">מחיקת כל הנתונים</button><div class="note"><h3>הוספה למסך הבית באנדרואיד</h3><p>פתחי את הקישור ב־Chrome. בתפריט שלוש הנקודות בחרי ״התקנת אפליקציה״ או ״הוספה למסך הבית״. ההפעלה המקומית אינה דורשת חשבון. קישור התצוגה הפרטי עשוי לבקש כניסה ל־ChatGPT.</p><p id="offline-status">בודקת זמינות ללא אינטרנט…</p></div></section>`}
function completion(){const d=day();const entries=[['דגש ליום',d.morning.focus.length||d.morning.custom],['אוכל',d.meals.some(m=>m.items.length)],['שתייה',d.drinks.length],['צעדים',d.steps!=null],['פעילות',d.exercise||d.activities.length],['סוף יום',d.evening.thanks.some(Boolean)||d.evening.improve||d.evening.help||d.evening.continue||d.evening.learn||d.evening.self],['היערכות למחר',d.tomorrow.focus||d.tomorrow.prep||d.tomorrow.help||d.tomorrow.movement||d.tomorrow.challenge]];return '<div class="completion" aria-label="מצב הדיווח">'+entries.map(([label,done])=>'<span>'+label+': '+(done?'דיווחת':'טרם דיווחת')+'</span>').join('')+'</div>'}
function render(){day();document.getElementById('date').value=selected;document.getElementById('dateLabel').textContent=new Date(selected+'T12:00:00').toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'});document.querySelectorAll('#tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});document.getElementById('view').innerHTML=({morning:morningView,food:foodView,water:waterView,movement:movementView,body:trackingView,evening:eveningView,trends:trackingView,settings:settingsView})[tab]();refreshSummary();checkReminders();offlineStatus();}
function freshMeal(type){return{id:uid(),type,time:new Date().toTimeString().slice(0,5),planned:true,items:[],habits:{},hunger:'',satiety:'',influence:'',note:''}}
function mealCopy(m){let n=freshMeal(m.type);n.items=clone(m.items).map(i=>({...i,id:uid()}));n.planned=m.planned;return n}
function emptyItem(){return{id:uid(),name:'',qty:null,unit:'גרם',base:null,cal:null,pro:null,carbs:null,fat:null,fiber:null,estimated:false}}
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function csvText(){const headers=['תאריך','דיווח מזון מלא','קלוריות','חלבון','סיכום חלקי','מים מ״ל','סך נוזלים מ״ל','שתייה ביעד מ״ל','צעדים','פעילויות','דקות פעילות','משקל','היקף מותניים','דגש יומי','עמידה ביעד לפי דיווח','יעד קלוריות','יעד חלבון','יעד שתייה','יעד צעדים','אוכל','פחמימות גרם','שומן גרם','סיבים גרם','פחמימות חלקי','שומן חלקי','סיבים חלקי','יעד פחמימות','יעד שומן','יעד סיבים','הצלחות','חסמים','הערת הצלחה','הערת חסם'];const rows=Object.entries(db.days).filter(([k,d])=>d.touched).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,d])=>{const t=totals(d);return[k,d.full?'כן':'לא',metricTotal(d,'cal').value??'',metricTotal(d,'pro').value??'',t.n&&!t.complete?'כן':'',liquid(d,['מים']),liquid(d),liquid(d,d.goals.drinkTypes),d.steps,d.activities.length?d.activities.length:d.exercise==='לא'?0:'',d.activities.length?d.activities.reduce((s,a)=>s+a.minutes,0):d.exercise==='לא'?0:'',d.body.weight,d.body.waist,[...d.morning.focus,d.morning.custom].filter(Boolean).join(' | '),d.evening.calorieAnswer,d.goals.calories,d.goals.protein,d.goals.water,d.goals.steps,d.meals.map(m=>mealType(m.type)+': '+m.items.map(i=>i.name+' '+(i.qty??'')+' '+i.unit).join(', ')).join(' | '),...['carbs','fat','fiber'].map(key=>metricTotal(d,key).value??''),...['carbs','fat','fiber'].map(key=>metricTotal(d,key).value!=null&&!metricTotal(d,key).complete?'כן':''),d.goals.carbs,d.goals.fat,d.goals.fiber,(d.evening.successes||[]).join(' | '),(d.evening.barriers||[]).join(' | '),d.evening.successNote,d.evening.barrierNote]});return '\uFEFF'+[headers,...rows].map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function checkReminders(){let box=document.getElementById('reminder');if(selected!==localDate()){box.textContent='';return}let now=new Date().toTimeString().slice(0,5);const reminders=db.settings.reminders.filter(r=>r.time<=now);let messages=reminders.map(r=>r.time+' · '+r.text);if(db.settings.visible.weight&&db.settings.weighDays.includes(new Date().getDay())&&day().body.weight==null)messages.push('זה אחד מימי השקילה שבחרת. תוכלי לדווח בשתייה ותנועה.');box.textContent=messages.join(' • ')}
function syncTomorrow(){const next=db.days[shift(selected,1)];if(!next)return;next.morning.inherited=clone(day().tomorrow);if(!next.touched){next.morning.custom=day().tomorrow.focus;next.morning.meals=plannedMeals(day().tomorrow);next.morning.activity=day().tomorrow.movement}}
function refreshFood(){if(tab!=='food')return;day().meals.forEach((m,mi)=>{m.items.forEach((it,ii)=>{let e=document.getElementById(`item-total-${mi}-${ii}`);if(e)e.textContent=itemTotal(it);let summary=document.getElementById(`item-summary-${mi}-${ii}`);if(summary)summary.textContent=compactNutrition({meals:[{items:[it]}]})});let e=document.getElementById('meal-total-'+mi),t=totals({meals:[m]});if(e)e.textContent=nutrientText({meals:[m]});let summary=document.getElementById('meal-summary-'+mi);if(summary)summary.textContent=compactNutrition({meals:[m]})})}
document.addEventListener('input',e=>{let el=e.target,p=el.dataset.path;if(!p)return;let value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(el.type==='number'&&value!=null&&(!Number.isFinite(value)||value<Number(el.min||0)||(el.max&&value>Number(el.max)))){el.setCustomValidity('הזיני מספר בטווח המותר');el.reportValidity();return}el.setCustomValidity('');set(p,value);if(p.startsWith('day.tomorrow'))syncTomorrow();save(p.startsWith('day.'));refreshSummary();refreshFood();refreshEveningGoals()});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();return}let a=b.dataset.action;if(!a)return;const d=day(),mi=Number(b.dataset.mi),ii=Number(b.dataset.ii),idx=Number(b.dataset.index),v=b.dataset.value;let changed=true;
switch(a){case'tab':tab=v;changed=false;break;case'date':selected=v;tab='body';changed=false;break;case'answer':set(b.dataset.path,b.dataset.path.endsWith('.planned')?v==='מתוכננת':v);break;case'focus':if(d.morning.focus.includes(v))d.morning.focus=d.morning.focus.filter(x=>x!==v);else if(d.morning.focus.length<2)d.morning.focus.push(v);else{toast('בחרי עד שני דגשים');return}break;case'task':d.tomorrow.tasks=d.tomorrow.tasks.includes(v)?d.tomorrow.tasks.filter(x=>x!==v):[...d.tomorrow.tasks,v];syncTomorrow();break;
case'reflection':{const key=b.dataset.key;if(!['successes','barriers'].includes(key))return;const list=d.evening[key]||[];d.evening[key]=list.includes(v)?list.filter(x=>x!==v):[...list,v];break}case'plannedSnack':case'unplannedSnack':{let m=freshMeal('snack');m.planned=a==='plannedSnack';d.meals.push(m);break}case'cup':d.drinks.push({id:uid(),type:'מים',amount:cupSize(d)});break;case'cupGoal':{const n=prompt('כמה כוסות ביום? (אפשר להשאיר ריק)',db.settings.water==null?'':db.settings.water/(db.settings.cupMl||250));if(n===null)return;if(n.trim()==='')db.settings.water=null;else if(Number.isFinite(Number(n))&&Number(n)>=0)db.settings.water=Number(n)*(db.settings.cupMl||250);else{toast('הזיני מספר כוסות תקין');return}changed=false;break}case'addMeal':d.meals.push(freshMeal(v));break;case'removeMeal':if(!confirm('למחוק את הארוחה?'))return;d.meals.splice(mi,1);break;case'addItem':d.meals[mi].items.push(emptyItem());break;case'removeItem':d.meals[mi].items.splice(ii,1);break;
case'saveFood':{let item=d.meals[mi].items[ii];if(!item.name.trim()){toast('כתבי שם למזון לפני השמירה');return}db.foods.push(clone(item));toast('המזון נשמר');break}case'useFood':{let value=document.getElementById('saved-food-'+mi).value;if(value==='')return;let f=clone(db.foods[Number(value)]);f.id=uid();d.meals[mi].items.push(f);break}
case'saveMeal':{if(!d.meals[mi].items.length){toast('הוסיפי פריטי מזון לפני שמירת הארוחה');return}let title=prompt('איך לקרוא לארוחה הקבועה?',mealType(d.meals[mi].type));if(!title?.trim())return;db.templates.push({...mealCopy(d.meals[mi]),title:title.trim()});toast('הארוחה נשמרה');break}
case'saveBreakfast':if(!d.meals[mi].items.length){toast('הוסיפי קודם פריטי מזון');return}db.breakfast=mealCopy(d.meals[mi]);toast('הבוקר הקבוע שלך נשמר');break;case'useBreakfast':if(!db.breakfast){toast('הוסיפי ארוחת בוקר והגדירי אותה כבוקר הקבוע שלך');return}d.meals.push(mealCopy(db.breakfast));break;case'copyMeal':d.meals.push(mealCopy(db.days[shift(selected,-1)].meals[Number(document.getElementById('copy-meal').value)]));break;case'useTemplate':d.meals.push(mealCopy(db.templates[Number(document.getElementById('template-meal').value)]));break;
case'water':d.drinks.push({id:uid(),type:'מים',amount:Number(v)});break;case'removeDrink':d.drinks.splice(idx,1);break;case'editDrink':{let amount=prompt('כמות במ״ל',d.drinks[idx].amount);if(amount===null)return;if(!(Number(amount)>0)){toast('הזיני כמות גדולה מאפס');return}let type=prompt('סוג משקה: '+drinks.join(', '),d.drinks[idx].type);if(type===null)return;if(!drinks.includes(type)){toast('בחרי סוג משקה מהרשימה');return}d.drinks[idx].amount=Number(amount);d.drinks[idx].type=type;break}
case'removeActivity':d.activities.splice(idx,1);break;case'editActivity':{const item=d.activities[idx],minutes=prompt('משך בדקות',item.minutes);if(minutes===null)return;if(!(Number(minutes)>0)){toast('הזיני משך גדול מאפס');return}const type=prompt('סוג הפעילות',item.type);if(!type?.trim())return;const note=prompt('הערה',item.note);if(note===null)return;Object.assign(item,{minutes:Number(minutes),type:type.trim(),note});item.met=activityMet(item.type,item.effort||'רגילה');item.kcal=estimateActivity(item.met,item.weightKg,item.minutes);break}
case'applyGoals':if(!confirm('להחליף את היעדים של היום הנבחר?'))return;d.goals=clone(db.settings);break;case'drinkType':db.settings.drinkTypes=db.settings.drinkTypes.includes(v)?db.settings.drinkTypes.filter(x=>x!==v):[...db.settings.drinkTypes,v];changed=false;break;case'weighDay':{let n=Number(v);db.settings.weighDays=db.settings.weighDays.includes(n)?db.settings.weighDays.filter(x=>x!==n):[...db.settings.weighDays,n];changed=false;break}case'removeReminder':db.settings.reminders.splice(idx,1);changed=false;break;case'deleteFood':db.foods.splice(idx,1);changed=false;break;case'deleteTemplate':db.templates.splice(idx,1);changed=false;break;case'clearBreakfast':db.breakfast=null;changed=false;break;
case'backup':download('היום-שלי-גיבוי-'+localDate()+'.json',safeToSave?JSON.stringify(db,null,2):localStorage.getItem(KEY),'application/json');toast('קובץ הגיבוי מוכן להורדה');return;case'csv':download('היום-שלי-'+localDate()+'.csv',csvText(),'text/csv;charset=utf-8');return;case'reset':if(!confirm('למחוק את כל הנתונים, כולל מזונות, ארוחות והגדרות? כדאי לשמור גיבוי קודם.'))return;db=defaults();safeToSave=true;startupError='';changed=false;toast('הנתונים נמחקו');break;default:return}
save(changed);render()});
document.addEventListener('submit',e=>{e.preventDefault();const id=e.target.id,d=day();if(id==='drink-form'){const amount=Number(document.getElementById('drink-amount').value);if(!(amount>0))return;d.drinks.push({id:uid(),type:document.getElementById('drink-type').value,amount})}else if(id==='activity-form'){const minutes=Number(document.getElementById('activity-minutes').value);if(!(minutes>0))return;const type=document.getElementById('activity-type').value,effort=document.getElementById('activity-effort').value,weightKg=Number(document.getElementById('activity-weight').value)||null,met=activityMet(type,effort);d.activities.push({id:uid(),type,minutes,note:document.getElementById('activity-note').value,effort,weightKg,met,kcal:estimateActivity(met,weightKg,minutes)});d.exercise='כן'}else if(id==='reminder-form'){db.settings.reminders.push({time:document.getElementById('reminder-time').value,text:document.getElementById('reminder-text').value.trim()})}else return;save(id!=='reminder-form');render()});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('קובץ הגיבוי גדול מדי');const incoming=validate(JSON.parse(await f.text()));if(!confirm('השחזור יחליף את כל הנתונים הנוכחיים בנתוני הקובץ. להמשיך?'))return;db=incoming;safeToSave=true;startupError='';save(false);render();toast('הגיבוי שוחזר')}catch(err){toast('השחזור לא בוצע: '+err.message)}finally{e.target.value=''}});
document.getElementById('date').addEventListener('change',e=>{if(e.target.value){selected=e.target.value;render()}});document.getElementById('prev').onclick=()=>{selected=shift(selected,-1);render()};document.getElementById('next').onclick=()=>{selected=shift(selected,1);render()};document.getElementById('today').onclick=()=>{selected=localDate();render()};
let offlineReady=false;function offlineStatus(){let e=document.getElementById('offline-status');if(e)e.textContent=offlineReady?'האפליקציה מוכנה לשימוש ללא אינטרנט אחרי טעינה מוצלחת.':'השימוש ללא אינטרנט דורש טעינה מוצלחת של כל קובצי האפליקציה בקישור HTTPS.'}
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;offlineStatus()}).catch(()=>{offlineReady=false;offlineStatus()});

function plannedMeals(plan){if(!plan.menu)return plan.prep||'';return Object.entries(plan.menu).filter(([k,v])=>v).map(([k,v])=>({breakfast:'בוקר',lunch:'צהריים',dinner:'ערב',snacks:'ביניים'}[k]||k)+': '+v).join('\n')}
function cupSize(d){return d.goals.cupMl||250}
function feedback(d){const t=totals(d),out=[];if(!d.full||!t.complete)out.push('דיווח האוכל עדיין חלקי. אין מספיק מידע להשוואה ליעדי הקלוריות והחלבון.');else if(d.goals.protein>0&&t.pro<d.goals.protein)out.push('דיווחת '+fmt(t.pro)+' ג׳ חלבון מול יעד של '+fmt(d.goals.protein)+'. בתכנון למחר תוכלי לשלב מקור חלבון באחת הארוחות.');else if(d.goals.calories>0&&t.cal>d.goals.calories)out.push('דיווחת '+fmt(t.cal)+' קלוריות מול יעד של '+fmt(d.goals.calories)+'. מה עזר ומה הקשה היום? תוכלי לתכנן מחר ארוחות שמתאימות לך, בלי לפצות על היום.');const water=liquid(d,d.goals.drinkTypes);if(water!=null&&d.goals.water>0&&water<d.goals.water)out.push('דיווחת '+fmt(water/cupSize(d))+' כוסות מול יעד של '+fmt(d.goals.water/cupSize(d))+'. אולי יעזור לשלב כוס לצד הארוחות.');if(d.meals.some(m=>m.type==='snack'&&!m.planned))out.push('דיווחת ביניים לא מתוכננת. האם הכנת ביניים זמינה למחר תעזור לך?');if(d.steps!=null&&d.goals.steps>0&&d.steps<d.goals.steps)out.push('הצעדים שדיווחת נמוכים מהיעד שקבעת. אם מתאים לך, תוכלי לבחור זמן להליכה קצרה מחר.');return out.length?out.slice(0,2):['בחרי דבר אחד שעזר לך היום ושווה להמשיך איתו מחר.']}
function itemView(item,mi,ii){return `<details class="food-item" ${!item.name?'open':''}><summary>${esc(item.name)||'פריט חדש'}<small id="item-summary-${mi}-${ii}">${compactNutrition({meals:[{items:[item]}]})}</small></summary>${detailedItemView(item,mi,ii)}</details>`}
function waterView(){const d=day(),size=cupSize(d),water=liquid(d,['מים']),all=liquid(d),goal=liquid(d,d.goals.drinkTypes);const count=water==null?0:Math.min(16,Math.floor(water/size));return `<section class="card"><span class="eyebrow">כוס ועוד כוס</span><h2>השתייה שלי</h2><p>ביעד: ${goal==null?'טרם דיווחת':fmt(goal/size)+' כוסות'}${d.goals.water!=null?' מתוך '+fmt(d.goals.water/size):''}</p><div class="cups" aria-hidden="true">${Array.from({length:Math.max(8,count)},(_,i)=>`<span class="cup ${i<count?'filled':''}"></span>`).join('')}</div><p class="hint">כוס ביום הזה = ${fmt(size)} מ״ל</p><button class="primary wide" data-action="cup">+ שתיתי כוס מים</button><p class="hint">מים: ${water==null?'טרם דיווחת':fmt(water/size)+' כוסות'} · כל הנוזלים: ${all==null?'טרם דיווחת':fmt(all/size)+' כוסות'}</p><details><summary>משקה אחר או כמות אחרת</summary><form id="drink-form"><label for="drink-type">סוג משקה</label><select id="drink-type">${drinks.map(x=>`<option>${x}</option>`).join('')}</select><label for="drink-amount">כמות במ״ל</label><input id="drink-amount" type="number" min="1" required><button type="submit">הוספה</button></form></details><details><summary>הכוסות שדיווחתי · עריכה ומחיקה</summary>${d.drinks.map((x,i)=>`<div class="log"><span>${esc(x.type)} · ${fmt(x.amount/size)} כוסות</span><div class="log-actions"><button class="small" data-action="editDrink" data-index="${i}">עריכה</button><button class="small danger" data-action="removeDrink" data-index="${i}">מחיקה</button></div></div>`).join('')||'<p>טרם דיווחת</p>'}</details></section>`}
// MET values from the 2024 Adult Compendium; gross expenditure estimate includes resting energy.
function activityMet(type,effort){const values={'הליכה':{'רגילה':3.8,'נמרצת':4.8},'אימון כוח':{'רגילה':3.5,'נמרצת':6},'יוגה':{'רגילה':2.3,'נמרצת':4},'תנועתיות':{'רגילה':2.3},'פילאטיס':{'רגילה':2.8}};return values[type]?.[effort]??null}
function estimateActivity(met,weight,minutes){return met>0&&weight>0&&minutes>0?Math.round(met*3.5*weight/200*minutes):null}
function movementView(){const d=day();const latest=Object.entries(db.days).filter(([k,x])=>k<=selected&&x.body.weight>0).sort((a,b)=>b[0].localeCompare(a[0]))[0]?.[1].body.weight;return `<section class="card"><span class="eyebrow">זמן לתנועה</span><h2>הפעילות שלי</h2>${d.morning.activity?`<p class="note">${esc(d.morning.activity)}</p>`:''}<form id="activity-form"><div class="grid"><div class="field"><label for="activity-type">איזו פעילות?</label><select id="activity-type">${['הליכה','אימון כוח','יוגה','תנועתיות','פילאטיס','אחר'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="activity-minutes">כמה דקות?</label><input id="activity-minutes" type="number" min="1" required></div></div><details><summary>הערכת קלוריות והערה</summary><label for="activity-effort">עצימות</label><select id="activity-effort"><option>רגילה</option><option>נמרצת</option></select><label for="activity-weight">משקל לחישוב, ק״ג</label><input id="activity-weight" type="number" min="1" step="any" value="${esc(latest||db.settings.activityWeight)}"><label for="activity-note">הערה או שם פעילות אישית</label><input id="activity-note"><p class="hint">הערכה לפי סוג הפעילות, דקות ומשקל. כוללת את האנרגיה שהגוף מוציא במנוחה בזמן הפעילות. פעילות אישית או שילוב בלי מקדם מתאים יישמרו בלי חישוב. יוגה נמרצת מתייחסת ליוגה כוח. תנועתיות רגילה מתייחסת למתיחות קלות.</p><a href="https://pacompendium.com/" target="_blank" rel="noopener">מקור מקדמי הפעילות</a></details><button class="primary wide" type="submit">הוספת פעילות</button></form>${d.activities.map((a,i)=>`<div class="log"><div>${esc(a.type)} · ${fmt(a.minutes)} דקות<small>${a.kcal!=null?'כ־'+fmt(a.kcal)+' קלוריות · הערכה':'אין הערכת קלוריות'}${a.weightKg?' · לפי '+fmt(a.weightKg)+' ק״ג':''}</small>${esc(a.note)}</div><div class="log-actions"><button class="small" data-action="editActivity" data-index="${i}">עריכה</button><button class="small danger" data-action="removeActivity" data-index="${i}">מחיקה</button></div></div>`).join('')}<p class="hint">הפעילות לא משנה את יעד הקלוריות לאוכל.</p><details><summary>צעדים ודיווח על יום ללא אימון</summary>${field('כמה צעדים עשיתי?','day.steps','number',{step:1})}<p>יעד צעדים: ${fmt(d.goals.steps)}</p>${answers('האם התעמלתי היום?','day.exercise',['כן','לא'])}</details></section>`}
function trackingView(){return `<section class="card"><h2>המעקב השבועי שלי</h2><p class="hint">שבעת הימים עד ${selected}. הסיכום מבוסס רק על מה שדיווחת.</p>${weeklyNutrientsView()}${weeklyReflectionView()}</section><details class="card"><summary>מדידות ותחושה גופנית</summary>${legacyBodyView().split('<section class="card"><h2>איך אני מרגישה?')[1]?'<section class="card"><h2>איך אני מרגישה?'+legacyBodyView().split('<section class="card"><h2>איך אני מרגישה?')[1]:''}</details><details class="card"><summary>עוד מגמות, משקל והרגלי אכילה</summary>${legacyTrendsView()}</details>`}
function settingsView(){return `<section class="card"><h2>הכוס שלי</h2>${field('כמה מ״ל יש בכוס שלי?','root.settings.cupMl','number',{min:1})}<p class="hint">הגודל החדש יחול על ימים חדשים. דיווחים קודמים יישמרו בכמות המקורית.</p><p>יעד שתייה בהגדרות: ${db.settings.water==null?'ללא יעד':fmt(db.settings.water/(db.settings.cupMl||250))+' כוסות'}</p><button data-action="cupGoal">קביעת יעד בכוסות</button>${field('משקל להערכת פעילות, ק״ג, לבחירתי','root.settings.activityWeight','number',{min:1})}</section>${legacySettingsView().replace('שתייה ביום, מ״ל','שתייה ביום, מ״ל (מחושב מיעד הכוסות)')}`}


const nutrients=[['cal','calories','קלוריות',''],['pro','protein','חלבון','ג׳'],['carbs','carbs','פחמימות','ג׳'],['fat','fat','שומן','ג׳'],['fiber','fiber','סיבים','ג׳']];
const successOptions=['תכנון מראש','ארוחות מסודרות','ביניים מתוכננת','אכילה בנוכחות','שתייה לאורך היום','זמן לתנועה','דיבור מכבד לעצמי','הקשבה לרעב ולשובע'];
const barrierOptions=['עומס וחוסר זמן','ארוחה שלא הכנתי','רעב בין הארוחות','עייפות','לחץ','הסחות דעת','אכילה חברתית','קושי למצוא זמן לתנועה'];
function metricTotal(d,key){const items=d.meals.flatMap(m=>m.items);const known=items.filter(i=>Number.isFinite(i.qty)&&i.qty>0&&Number.isFinite(i.base)&&i.base>0&&Number.isFinite(i[key])&&i[key]>=0);return{value:known.length?known.reduce((a,i)=>a+i.qty/i.base*i[key],0):null,complete:items.length>0&&known.length===items.length,known:known.length,n:items.length,estimated:known.some(i=>i.estimated)}}
function compactNutrition(d){return ['cal','pro'].map(key=>{const t=metricTotal(d,key);return (key==='cal'?'קלוריות: ':'חלבון: ')+(t.value==null?'חסר':fmt(t.value)+(key==='pro'?' ג׳':''))+(t.value!=null&&!t.complete?' · חלקי':'')+(t.estimated?' · הערכה':'')}).join(' · ')}
function nutrientText(d){if(!d.meals.some(m=>m.items.length))return 'טרם הוספת מזון';const text=nutrients.map(([key,g,label,unit])=>{const t=metricTotal(d,key);return label+': '+(t.value==null?'חסר':fmt(t.value)+' '+unit)+(t.value!=null&&!t.complete?' (חלקי)':'')});if(nutrients.some(([key])=>!metricTotal(d,key).complete))text.push('הסיכום חלקי');if(d.meals.flatMap(m=>m.items).some(i=>i.estimated))text.push('הערכה');return text.join(' · ')}
function goalStatus(d,key,goalKey){const t=metricTotal(d,key),goal=d.goals[goalKey];if(t.value==null)return 'אין נתונים';if(!t.complete||!d.full)return 'סיכום חלקי, אין קביעה לגבי היעד';if(goal==null||!Number.isFinite(Number(goal)))return 'ללא יעד מוגדר';const diff=t.value-Number(goal);const status=Math.abs(diff)<0.000001?'הגעת ליעד':diff>0?'מעל היעד ב־'+fmt(diff):'מתחת ליעד ב־'+fmt(-diff);return status+(t.estimated?' · לפי הערכה':'')}
function goalTable(d){return `<div class="table-wrap"><table class="nutrient-table"><thead><tr><th>ערך</th><th>דיווח</th><th>יעד</th><th>השוואה</th></tr></thead><tbody>${nutrients.map(([key,g,label,unit])=>{const t=metricTotal(d,key);return `<tr><td>${label}</td><td>${t.value==null?'חסר':fmt(t.value)+' '+unit+(t.estimated?' · הערכה':'')}${t.value!=null&&!t.complete?' · חלקי':''}</td><td>${d.goals[g]==null?'לא הוגדר':fmt(d.goals[g])+' '+unit}</td><td>${goalStatus(d,key,g)}</td></tr>`}).join('')}</tbody></table></div><p class="hint">השוואה ליעדים שבחרת, בלי ציון. נציג הגעה או מעבר רק כשהדיווח מסומן כמלא וכל הערכים הרלוונטיים קיימים. מעל יעד חלבון או סיבים אינו בהכרח דבר שצריך לתקן.</p>`}
function refreshEveningGoals(){if(tab!=='evening')return;const el=document.getElementById('evening-goals');if(el)el.innerHTML=goalTable(day())}
function reflectionChips(label,key,options){const values=day().evening[key]||[];return `<h3>${label}</h3><div class="chips">${options.map(x=>`<button class="chip ${values.includes(x)?'selected':''}" aria-pressed="${values.includes(x)}" data-action="reflection" data-key="${key}" data-value="${x}">${x}</button>`).join('')}</div>`}
function weeklyMetric(key,goalKey){const dates=weekDates(),entries=dates.map(date=>({date,d:db.days[date]})).filter(({d})=>d?.touched&&d.full&&metricTotal(d,key).complete),withGoals=entries.filter(({d})=>d.goals[goalKey]!=null);return{count:entries.length,mean:average(entries.map(({d})=>metricTotal(d,key).value)),goalCount:withGoals.length,below:withGoals.filter(({d})=>metricTotal(d,key).value<d.goals[goalKey]-0.000001).length,reached:withGoals.filter(({d})=>Math.abs(metricTotal(d,key).value-d.goals[goalKey])<0.000001).length,above:withGoals.filter(({d})=>metricTotal(d,key).value>d.goals[goalKey]+0.000001).length}}
function weeklyNutrientsView(){const w=weeklyStats();return `<div class="note">${w.ds.length} ימים עם דיווח · ${w.acts.length} פעילויות · ${fmt(w.acts.reduce((n,a)=>n+a.minutes,0))} דקות</div><div class="table-wrap"><table><thead><tr><th>ערך</th><th>ממוצע</th><th>ימי דיווח מלא</th><th>מול היעד היומי ההיסטורי</th></tr></thead><tbody>${nutrients.map(([key,g,label,unit])=>{const x=weeklyMetric(key,g);return `<tr><td>${label}</td><td>${x.mean==null?'אין נתונים מלאים':fmt(x.mean)+' '+unit}</td><td>${x.count}</td><td>${x.goalCount?`${x.below} מתחת · ${x.reached} ביעד · ${x.above} מעל<br>מתוך ${x.goalCount} ימים עם יעד`:'אין ימים מלאים עם יעד'}</td></tr>`}).join('')}</tbody></table></div><p class="hint">לכל ערך בסיס נתונים נפרד. נתון חסר לא נחשב אפס. יום ללא דיווח לא נחשב יום מתחת ליעד. סיכומים שכוללים מזונות משוערים הם הערכה.</p><p class="hint">שתייה ממוצעת: ${fmt(average(w.water))} מ״ל (${w.water.length} ימים) · צעדים: ${fmt(average(w.steps))} (${w.steps.length} ימים). גודל כוס יכול להשתנות בין ימים, לכן הממוצע השבועי מוצג במ״ל.</p>`}
function weeklyReflection(key){const ds=weekDates().map(date=>db.days[date]).filter(d=>d?.touched),answered=ds.filter(d=>(d.evening[key]||[]).length),counts={};for(const d of answered)for(const v of new Set(d.evening[key]))counts[v]=(counts[v]||0)+1;return{days:answered.length,counts:Object.entries(counts).sort((a,b)=>b[1]-a[1])}}
function weeklyReflectionView(){const successes=weeklyReflection('successes'),barriers=weeklyReflection('barriers');if(!db.weekly[selected])db.weekly[selected]={continue:'',change:''};const notes=weekDates().filter(date=>db.days[date]?.evening.successNote||db.days[date]?.evening.barrierNote);return `<details><summary>הצלחות וחסמים שחזרו השבוע</summary><h3>מה עזר לי</h3><p class="hint">על בסיס ${successes.days} ימים עם בחירות</p>${successes.counts.length?successes.counts.map(([v,n])=>`<p>${esc(v)} · ${n} ימים</p>`).join(''):'<p class="hint">טרם סימנת דברים שעזרו.</p>'}<h3>מה הקשה עליי</h3><p class="hint">על בסיס ${barriers.days} ימים עם בחירות</p>${barriers.counts.length?barriers.counts.map(([v,n])=>`<p>${esc(v)} · ${n} ימים</p>`).join(''):'<p class="hint">טרם סימנת חסמים.</p>'}<p class="hint">אלו דברים שסימנת בעצמך. מספר החזרות לא מוכיח שהם גרמו לתוצאה התזונתית.</p>${notes.length?`<details><summary>הערות שכתבתי השבוע</summary>${notes.map(date=>`<div class="note"><strong>${date}</strong>${db.days[date].evening.successNote?`<p>הצלחה: ${esc(db.days[date].evening.successNote)}</p>`:''}${db.days[date].evening.barrierNote?`<p>חסם: ${esc(db.days[date].evening.barrierNote)}</p>`:''}</div>`).join('')}</details>`:''}${field('הצלחה שארצה להמשיך בשבוע הבא','root.weekly.'+selected+'.success','textarea')}${field('חסם שאוכל להקל עליו','root.weekly.'+selected+'.barrier','textarea')}${field('איזה שינוי קטן אנסה?','root.weekly.'+selected+'.experiment','textarea')}</details>`}

